  "check_code": """"Deterministic post-state checks for the Athena manifest disposition."""

from pathlib import Path
import re
import sqlite3


SYSTEM = "amazon_athena_checkout_analytics"
INCIDENT_ID = "INC-2025-09-17-CHK-042"
TARGET_MANIFEST = "ATH-MNF-20250917-CHK-073"
RETAINED_MANIFESTS = (
    "ATH-MNF-20250917-CHK-071",
    "ATH-MNF-20250917-CHK-072",
)
OTHER_MANIFESTS = RETAINED_MANIFESTS + ("ATH-MNF-20250917-CHK-074",)
BASE_COLUMNS = (
    "manifest_id, incident_id, service_dimension_id, business_service_id, "
    "proxy_resource_id, aws_region, source_file_name, window_start_edt, "
    "window_end_edt, export_row_count, imported_failed_attempts, checksum, "
    "redaction_policy, sla_claim_evidence_flag, reconciliation_status, "
    "source_system, created_at_edt"
)
IMMUTABLE_TARGET_COLUMNS = (
    "manifest_id, incident_id, service_dimension_id, business_service_id, "
    "proxy_resource_id, aws_region, source_file_name, window_start_edt, "
    "window_end_edt, export_row_count, imported_failed_attempts, checksum, "
    "redaction_policy, sla_claim_evidence_flag, source_system, created_at_edt"
)


def _db_path(workspace):
    return Path(workspace).resolve().parent / "system" / SYSTEM / "state.db"


def _baseline_path(workspace):
    return _db_path(workspace).with_name("state.db.pinned_backup")


def _row(path, columns, manifest_id):
    with sqlite3.connect(path) as connection:
        connection.row_factory = sqlite3.Row
        result = connection.execute(
            f"SELECT {columns} FROM request_export_manifests WHERE manifest_id = ?",
            (manifest_id,),
        ).fetchone()
    return dict(result) if result else None


def _rows(path, columns, manifest_ids):
    placeholders = ",".join("?" for _ in manifest_ids)
    with sqlite3.connect(path) as connection:
        return connection.execute(
            f"SELECT {columns} FROM request_export_manifests "
            f"WHERE incident_id = ? AND manifest_id IN ({placeholders}) "
            "ORDER BY manifest_id",
            (INCIDENT_ID, *manifest_ids),
        ).fetchall()


def _normalized(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())


def check_rounded_manifest_disqualified(workspace):
    try:
        row = _row(_db_path(workspace), "manifest_id, reconciliation_status", TARGET_MANIFEST)
        passed = bool(row and row["reconciliation_status"] == "not_eligible")
        detail = f"{TARGET_MANIFEST} reconciliation status is {row['reconciliation_status']!r}." if row else f"{TARGET_MANIFEST} is missing."
        return {"score": 1.0 if passed else 0.0, "detail": detail}
    except Exception as exc:
        return {"score": 0.0, "detail": f"Unable to inspect target manifest status: {exc}"}


def check_reconciliation_audit_note(workspace):
    try:
        row = _row(_db_path(workspace), "manifest_id, analyst_note", TARGET_MANIFEST)
        note = row["analyst_note"] if row else None
        normalized = _normalized(note)
        required_fragments = (
            "18700",
            "18742",
            "athmnf20250917chk071",
            "athmnf20250917chk072",
        )
        has_core_values = all(fragment in normalized for fragment in required_fragments)
        has_rounding = "round" in normalized
        has_request_level_basis = "requestlevel" in normalized
        has_evidence_meaning = "corrobor" in normalized or "evidence" in normalized
        has_retention_meaning = "retain" in normalized or "kept" in normalized
        passed = all((has_core_values, has_rounding, has_request_level_basis, has_evidence_meaning, has_retention_meaning))
        return {
            "score": 1.0 if passed else 0.0,
            "detail": f"Audit note semantic requirements satisfied={passed}; note={note!r}",
        }
    except Exception as exc:
        return {"score": 0.0, "detail": f"Unable to inspect reconciliation audit note: {exc}"}


def check_target_manifest_provenance_preserved(workspace):
    try:
        current = _row(_db_path(workspace), IMMUTABLE_TARGET_COLUMNS, TARGET_MANIFEST)
        baseline = _row(_baseline_path(workspace), IMMUTABLE_TARGET_COLUMNS, TARGET_MANIFEST)
        passed = current is not None and current == baseline
        detail = "Target manifest provenance and evidence flag match the pinned baseline." if passed else "A protected target-manifest field changed or the row is missing."
        return {"score": 1.0 if passed else 0.0, "detail": detail}
    except Exception as exc:
        return {"score": 0.0, "detail": f"Unable to compare target manifest provenance: {exc}"}


def check_other_incident_manifests_preserved(workspace):
    try:
        current = _rows(_db_path(workspace), BASE_COLUMNS, OTHER_MANIFESTS)
        baseline = _rows(_baseline_path(workspace), BASE_COLUMNS, OTHER_MANIFESTS)
        passed = len(current) == len(OTHER_MANIFESTS) and current == baseline
        detail = "Manifests 071, 072, and 074 match the pinned baseline." if passed else "A non-target incident manifest changed or is missing."
        return {"score": 1.0 if passed else 0.0, "detail": detail}
    except Exception as exc:
        return {"score": 0.0, "detail": f"Unable to compare non-target incident manifests: {exc}"}
